export type HeroVideoSources = {
  desktop: { mp4: string; webm?: string };
  mobile: { mp4: string; webm?: string };
  poster: {
    desktop: { webp: string; jpg: string; width: number; height: number };
    mobile: { webp: string; jpg: string; width: number; height: number };
  };
  description: string;
};

/**
 * Hero performance loop renditions generated by scripts/build-media.mjs from
 * public/jw-bg-vid.mp4 (DJ set in a wooden festival booth; 11.3 s seamless
 * loop). Replace the source file and re-run `npm run media:build` to swap in
 * new footage without touching layout code.
 *
 * The default opening uses still photographs: `photos.portraitNight` on
 * desktop and `photos.nightStage` on phones. The available loop is a
 * relatively low-resolution daytime DJ set. Set `heroHasVideo` to true to
 * restore the loop.
 */
export const heroVideo: HeroVideoSources = {
  desktop: {
    mp4: "/media/hero/hero-loop-desktop.mp4",
    webm: "/media/hero/hero-loop-desktop.webm",
  },
  mobile: {
    mp4: "/media/hero/hero-loop-mobile.mp4",
    webm: "/media/hero/hero-loop-mobile.webm",
  },
  poster: {
    desktop: { webp: "/media/hero/poster-desktop.webp", jpg: "/media/hero/poster-desktop.jpg", width: 1440, height: 1152 },
    mobile: { webp: "/media/hero/poster-mobile.webp", jpg: "/media/hero/poster-mobile.jpg", width: 864, height: 1152 },
  },
  description: "Justin Waves performing a DJ set in a sunlit wooden festival booth, headphones on, with the crowd beyond the decks.",
};

/** Whether a hero loop plays. When false the hero uses `photos.nightStage`. */
export const heroHasVideo = false;

