export type WatchVideo = {
  youtubeId: string;
  title: string;
};

/**
 * Authorized public videos. Add a YouTube ID and title to enable Watch in
 * navigation and on the homepage. The hero loop is not a Watch item.
 */
export const videos: readonly WatchVideo[] = [];

export function watchEnabled() {
  return videos.some((v) => Boolean(v.youtubeId));
}
